            phoenixTalents,
            goldenRetrieverTalents,
            libraryOwlTalents,
            risenSkeletonTalents,
            manaMothTalents,
            pixieTalents,
            shieldScarabTalents,
            foxTalents
        ] {
            for (key, value) in group {
                combined[key] = value
            }
        }
        return combined
    }()
}

